export const CHAT_STANDARD_DISCLAIMER_EN =
  "This content is generated by AI from information you provided and publicly available materials. It is for general information only and does not constitute licensed financial, insurance, tax, legal, or investment advice. Product terms, fees, benefits, coverage, and suitability are subject to the insurer's official documents and advice from licensed professionals. Please consult a qualified adviser before any purchase or configuration decision.";

export const CHAT_STANDARD_DISCLAIMER_ZH_TW =
  "本內容由 AI 根據用戶提供的資訊和公開資料生成，僅供一般資訊參考，不構成持牌財務、保險、稅務、法律或投資建議。保險產品條款、費用、收益、保障範圍和適用性應以保險公司正式文件及持牌專業人士意見為準。請在作出任何購買或配置決定前，諮詢合資格專業顧問。";

const CHAT_SHORT_DISCLAIMER =
  "以上内容仅供参考，不构成持牌建议。正式条款及适合性请以保险公司文件与合资格顾问意见为准。";

export const CHAT_SHORT_DISCLAIMER_EN =
  "The above is for general reference only and is not licensed advice. Official terms and suitability are subject to the insurer's documents and a qualified adviser.";

export const CHAT_SHORT_DISCLAIMER_ZH_TW =
  "以上內容僅供參考，不構成持牌建議。正式條款及適合性請以保險公司文件與合資格顧問意見為準。";

/** Common model / legacy inline endings (longest first for matching). */
const DISCLAIMER_SUFFIXES: string[] = [
  CHAT_STANDARD_DISCLAIMER_EN,
  CHAT_SHORT_DISCLAIMER_EN,
  CHAT_STANDARD_DISCLAIMER_ZH_TW,
  CHAT_STANDARD_DISCLAIMER,
  "「以上内容仅供一般信息参考，不构成持牌财务、保险、税务或法律建议；具体条款以保险公司正式文件及合资格专业人士意见为准。」",
  "以上内容仅供一般信息参考，不构成持牌财务、保险、税务或法律建议；具体条款以保险公司正式文件及合资格专业人士意见为准。",
  CHAT_SHORT_DISCLAIMER_ZH_TW,
  CHAT_SHORT_DISCLAIMER,
];

function trimBody(raw: string): string {
  return raw.replace(/\s+$/u, "").trim();
}

/**
 * Splits stored assistant text into user-facing body vs compliance footer for UI styling.
 */
export function splitAssistantMessage(content: string): {
  body: string;
  disclaimer: string | null;
} {
  const t = content.trim();
  if (!t) return { body: "", disclaimer: null };

  for (const suffix of DISCLAIMER_SUFFIXES) {
    if (t === suffix) {
      return { body: "", disclaimer: suffix };
    }
    if (t.endsWith(suffix)) {
      const before = t.slice(0, t.length - suffix.length);
      return { body: trimBody(before), disclaimer: suffix };
    }
    const sep = `\n\n${suffix}`;
    if (t.endsWith(sep)) {
      return {
        body: trimBody(t.slice(0, t.length - sep.length)),
        disclaimer: suffix,
      };
    }
  }

  return { body: t, disclaimer: null };
}
